class Solution {
  private static final int OFF = 1800, W = 57;

  private static void shiftOr(long[] dst, int dOff, long[] src, int sOff, int shift) {
    int words = shift / 64, bits = shift % 64;
    if (shift >= 0) {
      for (int i = W - 1; i >= words; i--) {
        long v = src[sOff + i - words] << bits;
        if (bits != 0 && i - words - 1 >= 0) v |= src[sOff + i - words - 1] >>> (64 - bits);
        dst[dOff + i] |= v;
      }
    } else {
      int sh = -shift;
      words = sh / 64;
      bits = sh % 64;
      for (int i = 0; i + words < W; i++) {
        long v = src[sOff + i + words] >>> bits;
        if (bits != 0 && i + words + 1 < W) v |= src[sOff + i + words + 1] << (64 - bits);
        dst[dOff + i] |= v;
      }
    }
  }

  public int maxProduct(int[] nums, int k, int limit) {
    if (Math.abs(k) > OFF) return -1;
    int P = limit + 2, cap = limit + 1;
    long[] cur = new long[2 * P * W];
    boolean[] live = new boolean[2 * P];
    for (int v : nums) {
      long[] nxt = cur.clone();
      boolean[] nl = live.clone();
      for (int p = 0; p < 2; p++) {
        for (int q = 0; q < P; q++) {
          int idx = p * P + q;
          if (!live[idx]) continue;
          long prod = v == 0 ? 0 : Math.min((long) q * v, cap);
          int nidx = (1 - p) * P + (int) prod;
          shiftOr(nxt, nidx * W, cur, idx * W, p == 0 ? v : -v);
          nl[nidx] = true;
        }
      }
      {
        int nidx = P + (int) Math.min(v, cap);
        int bit = OFF + v;
        nxt[nidx * W + bit / 64] |= 1L << (bit % 64);
        nl[nidx] = true;
      }
      cur = nxt;
      live = nl;
    }
    int bit = OFF + k;
    for (int q = limit; q >= 0; q--) {
      for (int p = 0; p < 2; p++) {
        int idx = p * P + q;
        if (live[idx] && (cur[idx * W + bit / 64] >>> (bit % 64) & 1L) != 0) return q;
      }
    }
    return -1;
  }
}
